 const draftKey=(kind:string)=>draftScope+':'+kind;
 useEffect(()=>{if(!['worker','photo'].includes(modal)||!workspaceId||busy)return;let active=true;const timer=setTimeout(()=>{void saveDraft({id:draftScope+':'+modal,form,file:file||undefined,updated:Date.now()}).then(()=>{if(active)setDraftStatus('Draft saved on this device. Submit when you’re online.')}).catch(()=>{if(active)setDraftStatus('Draft could not be saved on this device. Keep this form open.')})},400);return()=>{active=false;clearTimeout(timer)}},[modal,form,file,draftScope,workspaceId,busy]);
 const pendingWorkers=(data.workerRequests||[]).filter(r=>r.status==='pending').length;
