 useEffect(()=>{setDate(day(new Date().toISOString()));if(new URLSearchParams(window.location.search).has('google')||new URLSearchParams(window.location.search).has('googleSetup'))setPage('Settings');void load()},[]);
 useEffect(()=>{if(!connected||!workspaceId)return;let active=true,inFlight=false,failures=0;let timer:ReturnType<typeof setTimeout>;const controller=new AbortController();
 const schedule=()=>{if(active)timer=setTimeout(refresh,Math.min(30000,2000*2**failures))};
 const refresh=async()=>{clearTimeout(timer);if(inFlight)return;if(document.hidden){schedule();return;}inFlight=true;try{const r=await fetch('/api/workspace',{headers:{'x-workspace-id':workspaceId},signal:controller.signal,cache:'no-store'});const b=await readApiJson<{state:State;revision:number;access:Access;error?:string}>(r);if(!r.ok){if(active&&(r.status===401||r.status===403)){setConnected(false);setError(b.error||'Sign in again to access your workspace')}throw Error(b.error||'Live updates unavailable')};if(!b.state||!b.access||!Number.isFinite(b.revision))throw Error('Invalid live update');if(active){failures=0;setLiveStatus('Live updates · about every 2s');if(b.revision>=latestRevision.current){latestRevision.current=b.revision;setData(b.state);setRevision(b.revision);setServerAccess(b.access)}}}catch{if(active){failures=Math.min(failures+1,4);setLiveStatus(navigator.onLine?'Reconnecting live updates…':'Offline · updates paused')}}finally{inFlight=false;schedule()}};
 const offline=()=>setLiveStatus('Offline · drafts stay on this device');const resume=()=>{if(!document.hidden)void refresh()};schedule();window.addEventListener('offline',offline);window.addEventListener('focus',resume);window.addEventListener('online',resume);document.addEventListener('visibilitychange',resume);return()=>{active=false;controller.abort();clearTimeout(timer);window.removeEventListener('offline',offline);window.removeEventListener('focus',resume);window.removeEventListener('online',resume);document.removeEventListener('visibilitychange',resume)}},[connected,workspaceId]);
 useEffect(()=>{const params=new URLSearchParams(window.location.search);const initial=params.has('notifications')?'Notifications':params.has('google')?'Settings':'Overview';setPage(initial);window.history.replaceState({hewersPage:initial,hewersTab:'Stock overview'},'');const back=(event:PopStateEvent)=>{const next=event.state?.hewersPage;if(!Object.hasOwn(pageLabels,next))return;setPage(next);setTab(event.state?.hewersTab||'Stock overview');setMobile(false);setQuery('');setError('');window.scrollTo(0,0)};window.addEventListener('popstate',back);return()=>window.removeEventListener('popstate',back)},[]);
 useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),4000);return()=>clearTimeout(timer)},[toast]);
