 useEffect(()=>{if(!modal&&!lightbox)return;const previous=document.activeElement as HTMLElement;const dialog=document.querySelector('.modal, .lightbox') as HTMLElement;const controls=()=>Array.from(dialog?.querySelectorAll<HTMLElement>('button:not([disabled]),input,select,a[href]')||[]);controls()[0]?.focus();const trap=(e:KeyboardEvent)=>{if(e.key!=='Tab')return;const items=controls(),first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}};document.addEventListener('keydown',trap);return()=>{document.removeEventListener('keydown',trap);previous?.focus()}},[modal,lightbox]);
 async function load(target=workspaceId){setBusy(true);setError('');try{const r=await fetch('/api/workspace',{headers:target?{'x-workspace-id':target}:{}});const b:any=await r.json();if(!r.ok)throw Error(b.error);setData(b.state);setRevision(b.revision);setActor(b.actor);setServerAccess(b.access);setWorkspaceId(b.access.owner);setWorkspaces(b.workspaces);setConnected(true);setSite('all');}catch(e:any){setError(e.message);if(e.message?.startsWith('PASSWORD_REQUIRED'))window.location.href='/login'}finally{setBusy(false);setLoading(false)}}

 const relevant=(x:any)=>site==='all'||x.siteId===site;
 const search=(text:string)=>text.toLowerCase().includes(query.toLowerCase());
 const workers=data.workers.filter(w=>relevant(w)&&!w.archivedAt),materials=data.materials.filter(relevant),photos=data.photos.filter(relevant);
