 const Empty=({text,action,label}:{text:string;action?:()=>void;label?:string})=><div className="empty"><Layers size={30}/><h3>{text}</h3><p>Your records will appear here as your team adds updates.</p>{action&&<button className="btn" onClick={action}><Plus size={16}/>{label}</button>}</div>;
