function Stat({title,value,label,icon,trend,warning=false}:any){return <div className={'stat '+(warning?'warning':'')}><div className="stat-top"><span>{title}</span><span className="stat-icon">{icon}</span></div><strong className="stat-value">{String(value).padStart(2,'0')}</strong><p>{label}</p><div className="stat-bottom"><span className="dot"/>{trend}</div></div>}

function Field({label,name,type='text',required=true,form,setForm}:any){return <label>{label}<input type={type} required={required} min={type==='number'?0:undefined} step={type==='number'?'0.001':undefined} value={form[name]??''} onChange={e=>setForm((f:any)=>({...f,[name]:e.target.value}))}/></label>}
